/// WebIDL `(Node or DOMString)`.
#[derive(Debug, Clone, PartialEq)]
pub enum NodeOrDomString {
    /// `Node`
    Node(Handle<Node>),
    /// `DOMString`
    DomString(String),
}

#[cfg(feature = "v8")]
impl NodeOrDomString {
    /// Converts a JavaScript value to this union.
    ///
    /// Tested arms keep declaration order except callback interfaces follow
    /// callable, platform, buffer and iterable arms. A sequence uses
    /// `@@iterator`; the first arm without a test
    /// is the fallback.
    pub fn from_v8<'s>(
        scope: &mut v8::PinScope<'s, '_>,
        value: v8::Local<'s, v8::Value>,
    ) -> Result<Self, JsError> {
        if let Some(inner) = interface_handle_from_v8::<Node>(scope, value)? {
            return Ok(NodeOrDomString::Node(inner));
        }
        (string_from_v8(scope, value)).map(NodeOrDomString::DomString)
    }

    /// Converts this union to a JavaScript value.
    pub fn to_v8<'s>(
        &self,
        scope: &mut v8::PinScope<'s, '_>,
    ) -> Result<v8::Local<'s, v8::Value>, JsError> {
        match self {
            NodeOrDomString::Node(inner) => {
                let value = *inner;
                handle_to_v8::<Node>(scope, value)
            }
            NodeOrDomString::DomString(inner) => {
                let value = inner.clone();
                string_to_v8(scope, &value)
            }
        }
    }
}

#[cfg(feature = "quickjs")]
impl<'js> rquickjs::FromJs<'js> for NodeOrDomString {
    fn from_js(ctx: &rquickjs::Ctx<'js>, value: rquickjs::Value<'js>) -> rquickjs::Result<Self> {
        if quickjs_is_interface(ctx, &value, "Node") {
            return <Handle<Node> as rquickjs::FromJs>::from_js(ctx, value).map(NodeOrDomString::Node);
        }
        rquickjs::Coerced::<rquickjs::String>::from_js(ctx, value).and_then(|v| v.0.to_string_lossy()).map(NodeOrDomString::DomString)
    }
}

#[cfg(feature = "quickjs")]
impl<'js> rquickjs::IntoJs<'js> for NodeOrDomString {
    fn into_js(self, ctx: &rquickjs::Ctx<'js>) -> rquickjs::Result<rquickjs::Value<'js>> {
        match self {
            NodeOrDomString::Node(inner) => rquickjs::IntoJs::into_js(inner, ctx),
            NodeOrDomString::DomString(inner) => rquickjs::IntoJs::into_js(inner, ctx),
        }
    }
}

// Callback types. `Callback<Args, Ret>` is an opaque handle to a JavaScript
// callable; `Args` is the argument tuple and `Ret` the return type.

/// `callback EventHandlerNonNull = any (Event event);`
pub type EventHandlerNonNull = Callback<(Handle<Event>,), AnyValue>;

/// `callback OccurrenceHandler = undefined (DOMString details);`
pub type OccurrenceHandler = Callback<(String,), ()>;

/// `callback ErrorHandler = undefined (DOMString details);`
pub type ErrorHandler = Callback<(String,), ()>;

/// `callback interface EventListener` with the single operation `handleEvent`.
pub type EventListener = Callback<(Handle<Event>,), ()>;
